setslot('da',24,43,'[»Hvad nytter lærdom, hvis forstanden mangler?« — Hos Stobaios, tit. iii., s. 37 (1609).]')
setslot('da',24,44,'Gid disse domstole for retsplejens skyld var lige så rige på forstand og samvittighed som på lærdom.')
